[data-indicator-status] { --padding-left: 8px; display: flex; gap: 6px; align-items: center; padding-left: 12px; padding-right: 8px; height: var(--size-32); margin-right: 2px; border-radius: var(--rounded-full); transition: background var(--duration-short) ease; color: white; font-size: var(--size-13); font-weight: 500; white-space: nowrap; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; background: transparent; cursor: pointer; outline: none; }[data-indicator-status]:focus-visible { outline: 2px solid var(--color-blue-800,#3b82f6); outline-offset: 3px; }[data-status-dot] { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }[data-status-text-animation] {
  display: inline-flex; align-items: center; position: relative; overflow: hidden; height: 100%;
  & > * { white-space: nowrap; line-height: 1; }
  & [data-status-text-enter] { animation: 150ms cubic-bezier(0, 0, 0.2, 1) 0s 1 normal forwards running slotMachineEnter; }
}[data-status-ellipsis] { display: inline-flex; margin-left: 2px; }[data-status-ellipsis] span { animation: 1.2s ease 0s infinite normal none running ellipsisFade; margin: 0px 1px; }[data-status-ellipsis] span:nth-child(2) { animation-delay: 0.2s; }[data-status-ellipsis] span:nth-child(3) { animation-delay: 0.4s; }@keyframes ellipsisFade { 
  0%, 60%, 100% { opacity: 0.2; }
  30% { opacity: 1; }
}@keyframes slotMachineEnter { 
  0% { transform: translateY(0.8em); opacity: 0; }
  50% { opacity: 0.8; }
  100% { transform: translateY(0px); opacity: 1; }
}

